<template><div class="min-h-screen grid place-items-center overflow-hidden bg-[#0b1222] p-5"><div class="absolute inset-0 opacity-40" style="background:radial-gradient(circle at 20% 20%,#4f6cff 0,transparent 30%),radial-gradient(circle at 80% 80%,#7c3aed 0,transparent 28%)"></div><div class="relative grid w-full max-w-5xl overflow-hidden rounded-[30px] bg-white shadow-2xl lg:grid-cols-[1.05fr_.95fr]"><div class="hidden p-12 text-white lg:block" style="background:linear-gradient(145deg,#111a30,#1d2b52)"><div class="flex items-center gap-3"><div class="brand-mark">M</div><div class="text-lg font-extrabold">MauzoHub</div></div><div class="mt-24 max-w-md"><div class="text-xs font-bold uppercase tracking-[.2em] text-indigo-300">Business OS</div><h1 class="mt-4 text-5xl font-extrabold leading-[1.05] tracking-[-.05em]">Your sales, clients and cash flow. In one place.</h1><p class="mt-6 text-sm leading-7 text-slate-300">A focused workspace for growing businesses to manage customer accounts, invoices, payments and receivables.</p></div><div class="mt-20 text-[11px] text-slate-400">Secure workspace · Real-time account visibility</div></div><form @submit.prevent="submit" class="p-8 sm:p-12 lg:p-14"><div class="lg:hidden"><div class="text-2xl font-extrabold">MauzoHub</div><p class="mt-1 text-xs text-slate-400">Business management, simplified.</p></div><div class="mt-10 lg:mt-16"><div class="text-xs font-bold uppercase tracking-[.16em] text-indigo-600">Welcome back</div><h2 class="mt-3 text-3xl font-extrabold tracking-[-.04em]">Sign in to your workspace</h2><p class="mt-2 text-sm text-slate-500">Use your business account to continue.</p></div><div class="mt-8"><label class="label">Email</label><input v-model="email" class="input" type="email" required></div><div class="mt-4"><label class="label">Password</label><input v-model="password" class="input" type="password" required></div><p v-if="error" class="mt-4 rounded-xl bg-rose-50 p-3 text-xs font-semibold text-rose-600">{{error}}</p><button class="btn btn-primary mt-6 w-full py-3.5" :disabled="auth.loading">{{auth.loading?'Signing in…':'Sign in'}}</button><p class="mt-5 text-center text-[10px] text-slate-400">Demo account: admin@mauzohub.test · password</p></form></div></div></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../../stores/auth';const email=ref('admin@mauzohub.test'),password=ref('password'),error=ref('');const auth=useAuthStore(),router=useRouter();async function submit(){error.value='';try{await auth.login(email.value,password.value);router.push('/')}catch(e:any){error.value=e.response?.data?.message??'Unable to sign in.'}}</script>
